'use client';
import { cx } from '../lib/cx';
import { useControllable } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Bars, Dot, Fold, Radar, Spin, Swap, SwapIcon, Think } from '../lib/motion';
import '../designme.css';
import './step-loader.css';

export interface Step {
  /** Shown while the step runs, like "Reading Figma frames" */
  label: string;
  /** Shown once it is done, like "Read 4 frames". Falls back to label */
  done?: string;
}

export type StepLoaderGlyph = 'radar' | 'dots' | 'ring' | 'bars';

export interface StepLoaderProps {
  steps: Step[];
  /** Index of the step running now. steps.length (or more) means every step is done */
  current: number;
  /** The loader beside the running step */
  loader?: StepLoaderGlyph;
  /** Label once every step is done */
  doneLabel?: string;
  /** Whether the list of every step is open. Leave it out to let the row toggle it */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
}

const Loader = ({ kind }: { kind: StepLoaderGlyph }) =>
  kind === 'dots' ? <Think /> : kind === 'ring' ? <Spin /> : kind === 'bars' ? <Bars /> : <Radar />;

/** Named steps with a progress track. Click the row to see every step. */
export function StepLoader({ steps, current, loader = 'radar', doneLabel = 'Ready for review', open, defaultOpen = false, onOpenChange, className }: StepLoaderProps) {
  const [isOpen, setOpen] = useControllable(open, defaultOpen, onOpenChange);
  const n = steps.length, done = current >= n, at = Math.min(current, n - 1);
  return (
    <div data-dm="" className={cx('dm-stl dm-mx-ic', className)} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 10 }}>
      <button type="button" className="dm-stl-row dm-mx-press" aria-expanded={isOpen} onClick={() => setOpen(!isOpen)}>
        <span className="dm-stl-g"><SwapIcon id={done ? 'ok' : loader}>{done ? <span className="dm-stl-ok"><Icon name="ok" /></span> : <Loader kind={loader} />}</SwapIcon></span>
        <span className="dm-stl-t"><Swap className={cx('dm-stl-lab', !done && 'dm-shim')}>{done ? doneLabel : steps[at].label}</Swap><Swap className="dm-stl-n dm-num">{`${done ? n : at + 1}/${n}`}</Swap></span>
        <Icon name="chev-d" size="xs" className="dm-stl-chev" />
      </button>
      <div className="dm-stl-track" role="progressbar" aria-valuemin={0} aria-valuemax={n} aria-valuenow={done ? n : at}>
        {steps.map((_, i) => <i key={i} className={cx((done || i < current) && 'dm-on', !done && i === current && 'dm-run')} />)}
      </div>
      <Fold open={isOpen} className="dm-stl-fold">
        <ol className={cx('dm-stl-list dm-mx-rows', isOpen && 'dm-mx-play')}>
          {steps.map((s, i) => {
            const finished = done || i < current, running = !done && i === current;
            return (
              <li key={i} className={cx(finished && 'dm-done', running && 'dm-run')}>
                <span className="dm-g"><SwapIcon id={finished ? 'check' : running ? loader : 'dot'}>{finished ? <span className="dm-stl-ok"><Icon name="check" size="xs" /></span> : running ? <Loader kind={loader} /> : <Dot color="var(--dm-faint)" />}</SwapIcon></span>
                {finished ? s.done ?? s.label : s.label}
              </li>
            );
          })}
        </ol>
      </Fold>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Step loader ---------- */
/* a pill with the step in hand (its loader, its name shimmering while it runs, how far along), a track of one part a step
   under it, and a fold that lists every step. The list's marks sit centred under the pill's loader and its words start
   where the pill's do. The pill is a disclosure: pointing at it gives it a quiet fill, never a bigger shadow */
.dm-stl .dm-dm-main{gap:10px}
.dm-stl-row{display:flex;align-items:center;gap:10px;background:var(--dm-surface);border-radius:var(--dm-r-pill);box-shadow:var(--dm-shadow);height:40px;padding:0 14px 0 13px;font-size:13.5px;min-width:250px;transition:background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-stl-row:hover{background:color-mix(in srgb,var(--dm-fg) 4%,var(--dm-surface))}}
/* its motion (the core's motion pieces, owner, 26 Nov): a press on the pill shows at once (.mx-press); a mark that changes, the
   loader, the tick or a row's dot, crossfades in place (.mx-ic, iconSwap()); the list's rows settle one after another as it
   opens (.mx-rows) */
.dm-stl-g{width:16px;display:grid;place-items:center;color:var(--dm-fg)}
/* a finished step's tick is the vivid mark green */
.dm-stl-ok{display:grid;color:var(--dm-ok-mark)}
/* (the step and its count share one baseline, grouped in their own line, while the loader and the chevron stay centred on
   the pill; the count keeps the right end) */
.dm-stl-t{flex:1;min-width:0;display:flex;align-items:baseline;gap:10px;text-align:left}
.dm-stl-n{margin-left:auto;color:var(--dm-muted);font-size:12.5px}
.dm-stl-chev{color:var(--dm-muted);transition:transform .4s var(--dm-ease)}
.dm-stl-row[aria-expanded="true"] .dm-stl-chev{transform:rotate(180deg)}
.dm-stl-track{display:flex;gap:var(--dm-s-1);width:250px}
.dm-stl-track i{flex:1;height:3px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-line);position:relative;overflow:hidden}
.dm-stl-track i::after{content:"";position:absolute;inset:0;background:var(--dm-accent-mark,var(--dm-accent));transform:scaleX(0);transform-origin:left;transition:transform .9s var(--dm-ease)}
.dm-stl-track i.dm-on::after{transform:scaleX(1)}
.dm-stl-track i.dm-run::after{transform:scaleX(.45);transition-duration:2.2s}
.dm-stl-fold{width:250px}
.dm-stl-fold>div{margin-inline:-16px;padding-inline:var(--dm-s-4)}
/* (10px above and below: with a step's own 6px, the first and last steps' words are 16px from the card's edges) */
.dm-stl-list{list-style:none;margin:6px 0 18px;padding:10px 6px;background:var(--dm-surface);border-radius:calc(14px * var(--dm-rk-l,var(--dm-rk)));box-shadow:var(--dm-shadow)}
/* each step's mark centred under the pill's loader (21px in), its words where the pill's start (39px in) */
.dm-stl-list li{display:flex;align-items:center;gap:10px;padding:6px var(--dm-s-2) 6px 7px;font-size:13px;color:var(--dm-muted)}
.dm-stl-list li.dm-done{color:var(--dm-fg2)}.dm-stl-list li.dm-run{color:var(--dm-fg)}
.dm-stl-list li .dm-g{width:16px;display:grid;place-items:center;flex:none}
/* Clean (owner, 19 Nov): the pill is Status pill's Clean pill (36px, a hairline and a short shadow, 13px words) with its
   content 16px in; the list is a round card whose steps sit 8px in from its edges with their words 16px in, so its marks and
   words share the pill's columns (24px and 40px in). The track is the neutral rail with the accent filling it, the tick the
   vivid green, and the motion Clean's calm one */
/* the loader in the pill is the accent, which is white in Clean's dark mode (owner, 21 Nov: "accent color in light mode for
   clean") */
:root[data-style="clean"] .dm-stl-g,:root [data-style="clean"] .dm-stl-g,:root [data-style="clean"].dm-stl-g{color:var(--dm-accent-mark)}
:root[data-style="clean"] .dm-stl-row,:root [data-style="clean"] .dm-stl-row,:root [data-style="clean"].dm-stl-row{height:36px;gap:8px;padding:0 16px;font-size:13px}
:root[data-style="clean"] .dm-stl-t,:root [data-style="clean"] .dm-stl-t,:root [data-style="clean"].dm-stl-t{gap:8px}
:root[data-style="clean"] .dm-stl-chev,:root [data-style="clean"] .dm-stl-chev,:root [data-style="clean"].dm-stl-chev{transition:transform var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .dm-stl-track i,:root [data-style="clean"] .dm-stl-track i,:root [data-style="clean"].dm-stl-track i{background:var(--dm-rail)}
:root[data-style="clean"] .dm-stl-list,:root [data-style="clean"] .dm-stl-list,:root [data-style="clean"].dm-stl-list{margin:8px 0 16px;padding:8px;border-radius:var(--dm-r-card)}
:root[data-style="clean"] .dm-stl-list li,:root [data-style="clean"] .dm-stl-list li,:root [data-style="clean"].dm-stl-list li{gap:8px;padding:8px;line-height:20px}
/* the row's hover is Clean's one hover laid over its fill (owner, 21 Nov), easing in and out over 220ms */
:root[data-style="clean"] .dm-stl-row,:root [data-style="clean"] .dm-stl-row,:root [data-style="clean"].dm-stl-row{transition:box-shadow var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-stl-row:hover,:root [data-style="clean"] .dm-stl-row:hover,:root [data-style="clean"].dm-stl-row:hover{background:var(--dm-surface);box-shadow:var(--dm-shadow),inset 0 0 0 99px var(--dm-row)}}
/* (its press, the motion pieces' .mx-press: a step deeper than the hover, at once, in the hover's own layer) */
:root[data-style="clean"] .dm-stl-row.dm-mx-press:active,:root [data-style="clean"] .dm-stl-row.dm-mx-press:active,:root [data-style="clean"].dm-stl-row.dm-mx-press:active{box-shadow:var(--dm-shadow),inset 0 0 0 99px var(--dm-row-press);transition-duration:var(--dm-t-press)}
.dm-bars3{display:inline-flex;gap:2px;align-items:center;height:12px}
.dm-bars3 i{width:2.5px;height:100%;border-radius:var(--dm-r-tiny,2px);background:currentColor;animation:dm-b3 .9s var(--dm-ease-io) infinite}
.dm-bars3 i:nth-child(2){animation-delay:.15s}.dm-bars3 i:nth-child(3){animation-delay:.3s}
@keyframes dm-b3{0%,100%{transform:scaleY(.35)}50%{transform:scaleY(1)}}

